SELECT 'ALE-MATL-002-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-MATL-002'), 3, 'Concrete & Clay Masonry Units', 'Building Materials and Construction Methods', 'fact'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "CHB 4-inch: nominal 4\" thick (actual 3 7/8\"), used for non-load-bearing interior partitions", "type": "fact"}, {"text": "CHB 5-inch: nominal 5\" thick (actual 4 7/8\"), intermediate duty, mixed load-bearing applications", "type": "fact"}, {"text": "CHB 6-inch: nominal 6\" thick (actual 5 7/8\"), primary load-bearing unit, exterior walls", "type": "fact"}, {"text": "Standard CHB dimensions: 8\" wide (nominal) × 16\" long (nominal) × thickness", "type": "fact"}, {"text": "Actual CHB dimensions: 7 5/8\" × 15 5/8\" (accounts for mortar joint 3/8\")", "type": "fact"}, {"text": "Two-core and three-core designs: three-core provides better strength and thermal performance", "type": "fact"}, {"text": "Compressive strength: varies 500-2000 psi depending on material and design", "type": "fact"}, {"text": "Load-bearing CHB minimum 2000 psi (f''m = 1000-1500 psi typical mortar joint strength)", "type": "fact"}, {"text": "Non-load-bearing CHB 500-1000 psi acceptable (f''m = 500-1000 psi)", "type": "fact"}, {"text": "Hollow vs. solid: solid units rare but used for high-load applications", "type": "fact"}, {"text": "Standard brick: nominal 4\"×8\"×2 5/8\", actual 3 5/8\"×7 5/8\"×2 3/8\" (with mortar joints)", "type": "fact"}, {"text": "Modular brick: nominal 4\"×8\"×2 2/5\", actual 3 5/8\"×7 5/8\"×2 3/16\"", "type": "fact"}, {"text": "Compressive strength ranges: 4000-12000 psi for quality clay bricks", "type": "fact"}, {"text": "Grade MW (Moderate Weather): suitable for most outdoor exposure (>2500 psi)", "type": "fact"}, {"text": "Grade SW (Severe Weather): for areas with freeze-thaw cycles (<2500 psi acceptable)", "type": "fact"}, {"text": "Grade NW (No Weather): interior use only, lowest durability requirement", "type": "fact"}, {"text": "Color from clay mineral content: reds (iron oxide), browns (manganese), yellows (sulfur compounds)", "type": "fact"}, {"text": "Texture from manufacturing: smooth (wiped), rough (rustic), sand-struck (textured)", "type": "fact"}, {"text": "Efflorescence: white salt deposits on surface (typically temporary, salt migration)", "type": "fact"}, {"text": "Mortar: paste that bonds masonry units, consists of cement, lime, sand, and water", "type": "fact"}, {"text": "Type M Mortar: 1 part cement : 0.25 parts lime : 3 parts sand (highest strength)", "type": "fact"}, {"text": "Type S Mortar: 1 part cement : 0.5 parts lime : 4.5 parts sand (medium strength)", "type": "fact"}, {"text": "Type N Mortar: 1 part cement : 1 part lime : 6 parts sand (general purpose, most common)", "type": "fact"}, {"text": "Type O Mortar: 1 part cement : 2 parts lime : 9 parts sand (low strength, old structure repairs)", "type": "fact"}, {"text": "Type K Mortar: 1 part cement : 3 parts lime : 12 parts sand (very low strength, preservation only)", "type": "fact"}, {"text": "Compressive strength: Type M ~2500 psi, Type S ~1800 psi, Type N ~750 psi, Type O ~350 psi", "type": "fact"}, {"text": "Lime improves workability, water retention, and bond characteristics", "type": "fact"}, {"text": "Lime pozzolanic reaction (slow) improves durability and permeability", "type": "fact"}, {"text": "Sand grading: influences workability, water retention, bond with units", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-matl-002-03'
