SELECT 'ALE-MATL-003-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-MATL-003'), 3, 'Stainless Steel & Specialty Metals', 'Building Materials and Construction Methods', 'fact'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Austenitic (300 series, 304, 316): most corrosion resistant, non-magnetic, weldable", "type": "fact"}, {"text": "Ferritic (400 series, 430): moderate corrosion resistance, magnetic, brittle when welded", "type": "fact"}, {"text": "Martensitic (400 series, 410, 420): hardenable, used for springs/cutlery, less corrosion resistant", "type": "fact"}, {"text": "304 Stainless: general architectural use, 18% chromium + 8% nickel", "type": "fact"}, {"text": "316 Stainless: enhanced corrosion resistance from molybdenum, marine applications", "type": "fact"}, {"text": "Passivation: removal of iron contamination increases corrosion resistance", "type": "fact"}, {"text": "Pitting resistance equivalent number (PREN): higher = better pitting resistance", "type": "fact"}, {"text": "Chloride exposure: sea salt and de-icing salts cause pitting in lower-grade stainless", "type": "fact"}, {"text": "Galvanic corrosion: contact with dissimilar metals causes accelerated corrosion (use isolators)", "type": "fact"}, {"text": "Finish grades: polished (mirror), brushed (grain), satin, mill (dull)", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-matl-003-04'
