UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Nominal 2x4 lumber has actual dimensions of 1.5\" x 3.5\"", "type": "fact"}, {"text": "Nominal 2x6 lumber has actual dimensions of 1.5\" x 5.5\"", "type": "fact"}, {"text": "Nominal 2x8 lumber has actual dimensions of 1.5\" x 7.25\"", "type": "fact"}, {"text": "Nominal 2x10 lumber has actual dimensions of 1.5\" x 9.25\"", "type": "fact"}, {"text": "Nominal 2x12 lumber has actual dimensions of 1.5\" x 11.25\"", "type": "fact"}, {"text": "Nominal 4x4 lumber has actual dimensions of 3.5\" x 3.5\"", "type": "fact"}, {"text": "Nominal 4x6 lumber has actual dimensions of 3.5\" x 5.5\"", "type": "fact"}, {"text": "Nominal 6x6 lumber has actual dimensions of 5.5\" x 5.5\"", "type": "fact"}, {"text": "Nominal 8x8 lumber has actual dimensions of 7.25\" x 7.25\"", "type": "fact"}, {"text": "Reduction in size is due to drying and planing of green lumber", "type": "fact"}, {"text": "Select Grade: premium appearance, highest quality, knots less than 1\" maximum", "type": "fact"}, {"text": "Grade 1: good appearance, tight knots allowed, suitable for visible structural members", "type": "fact"}, {"text": "Grade 2: general purpose, knots up to 2\" allowed, standard for common applications", "type": "fact"}, {"text": "Grade 3: utility grade, larger knots and defects allowed, economy grade", "type": "fact"}, {"text": "Grade 4: lowest grade, significant defects allowed, for temporary structures only", "type": "fact"}, {"text": "Select Structural (SS): highest strength designation for primary structural members", "type": "fact"}, {"text": "Number 1 (No. 1): strong structural lumber, tight knots, suitable for beams and columns", "type": "fact"}, {"text": "Number 2 (No. 2): general structural lumber, larger knots permitted, most common for framing", "type": "fact"}, {"text": "Stud Grade: economical framing lumber, loose knots acceptable, not for main structural support", "type": "fact"}, {"text": "Utility Grade: very economical, large defects, temporary work only", "type": "fact"}, {"text": "Yakal (Dipterocarpus): hardwood, Class A strength, high durability, used for structural members, flooring, shipbuilding", "type": "fact"}, {"text": "Molave (Vitex parviflora): extremely hard, Class A, superior durability, used for posts, beams, piling, railway ties", "type": "fact"}, {"text": "Narra (Pterocarpus indicus): decorative hardwood, Class B, good for furniture, cabinetry, flooring, moderate structural use", "type": "fact"}, {"text": "Apitong (Dipterocarpus grandiflorus): strong hardwood, Class A, used for heavy structural beams, posts, bridges", "type": "fact"}, {"text": "Tanguile (Shorea polysperma): hardwood, Class B-C, used for general construction, framing, less critical members", "type": "fact"}, {"text": "Mahogany: decorative hardwood, Class B-C, used for furniture, paneling, ornamental work", "type": "fact"}, {"text": "Lauan/Meranti: medium hardwood, Class C, used for general framing, subflooring, less critical structures", "type": "fact"}, {"text": "Pili/Pilihan (Canarium ovatum): hardwood, Class B, used for fine cabinetry, decorative work", "type": "fact"}, {"text": "Acacia/Maulap: hardwood, Class C, used for general construction, fencing, utility applications", "type": "fact"}, {"text": "Bamboo: renewable, light construction, scaffolding, temporary structures, interior partitions", "type": "fact"}, {"text": "Class A (Yakal, Molave, Apitong): highest strength, used for main structural members bearing heavy loads", "type": "fact"}, {"text": "Class B (Narra, Mahogany, Pili): moderate to high strength, suitable for secondary structural members", "type": "fact"}, {"text": "Class C (Lauan, Acacia, Tanguile): lower strength, used for non-load-bearing members, partitions, flooring", "type": "fact"}, {"text": "Bending strength (modulus of rupture) highest in Class A species (can exceed 1,500 psi)", "type": "fact"}, {"text": "Compression along grain highest in Class A (parallel-to-grain compression)", "type": "fact"}, {"text": "Shear strength parallel to grain critical for joinery and connections", "type": "fact"}, {"text": "Modulus of elasticity (stiffness) related to deflection calculations in beams", "type": "fact"}, {"text": "Moisture content affects wood strength - dry lumber is stronger than green lumber", "type": "fact"}, {"text": "Design values reduced by moisture, temperature, load duration, and exposure factors", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-001-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "BOW: warp on the face of a board from end to end (major longitudinal curvature)", "type": "fact"}, {"text": "CUP: hollow across the face of a board (concave surface across width)", "type": "fact"}, {"text": "CROOK: warp along the edge line; also known as crown (lateral edge curvature)", "type": "fact"}, {"text": "KNOT/KNOTHOLE: tight knots usually not a problem; loose or dead knots (dark ring) may fall out leaving holes", "type": "fact"}, {"text": "SPLIT: crack going all the way through the piece of wood, commonly at the ends (radial drying defect)", "type": "fact"}, {"text": "TWIST: multiple bends in a board (helical warping along length)", "type": "fact"}, {"text": "CHECK: crack along wood''s annual growth rings, NOT passing through entire thickness (radial surface crack)", "type": "fact"}, {"text": "SHAKE: separation of grain between growth rings, often extending along board''s face (ring separation)", "type": "fact"}, {"text": "WANE: missing wood or untrimmed bark along the edge or corner of the piece (incomplete edge)", "type": "fact"}, {"text": "PITCH POCKET: opening in wood containing resin, may contain resin or be empty (structural defect)", "type": "fact"}, {"text": "PITCH STREAK: band of resin-saturated wood (darkened resin grain)", "type": "fact"}, {"text": "Moisture content (MC): weight of water divided by oven-dry weight of wood as percentage", "type": "fact"}, {"text": "Green lumber: MC above fiber saturation point (FSP), approximately 25-30%", "type": "fact"}, {"text": "Dry lumber: MC approximately 12-15% (kiln-dried or air-dried)", "type": "fact"}, {"text": "Lumber shrinks perpendicular to grain during drying, tangentially more than radially", "type": "fact"}, {"text": "Equilibrium moisture content (EMC): moisture content wood reaches in given climate (typically 8-15%)", "type": "fact"}, {"text": "Higher MC increases decay susceptibility and reduces strength properties", "type": "fact"}, {"text": "Drying stresses cause warping, checking, and splitting in lumber", "type": "fact"}, {"text": "Grade stamps indicate moisture condition at time of grading: S-GRN (green), S-DRY (≤19%), KD (kiln-dried)", "type": "fact"}, {"text": "Wood swells when exposed to moisture, shrinks when dried (anisotropic behavior)", "type": "fact"}, {"text": "Heartwood generally more durable than sapwood due to extractive content", "type": "fact"}, {"text": "Naturally durable species (Molave, Yakal, Narra) resistant to decay without treatment", "type": "fact"}, {"text": "Non-durable species require chemical preservation for decay resistance", "type": "fact"}, {"text": "Wood must have MC > 20% and be exposed to fungal spores for decay to occur", "type": "fact"}, {"text": "Pressure treatment forces preservatives into wood for long-term durability", "type": "fact"}, {"text": "Ground contact exposure: highest decay risk, requires appropriate preservation", "type": "fact"}, {"text": "Above-ground interior exposure: low decay risk, heartwood species often used untreated", "type": "fact"}, {"text": "Wet/marine environments: require highly durable species or treated lumber", "type": "fact"}, {"text": "Regular maintenance (paint, varnish, stain) prevents moisture ingress and extends life", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-001-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Class A Mix: 1 part cement : 2 parts sand : 4 parts gravel (high strength, 3000-3500 psi)", "type": "fact"}, {"text": "Class B Mix: 1 part cement : 2.5 parts sand : 5 parts gravel (moderate strength, 2000-2500 psi)", "type": "fact"}, {"text": "Class C Mix: 1 part cement : 3 parts sand : 6 parts gravel (general purpose, 1500-2000 psi)", "type": "fact"}, {"text": "Class A mix used for columns, beams, foundations requiring high strength", "type": "fact"}, {"text": "Class B mix used for floor slabs, walls, moderate-strength applications", "type": "fact"}, {"text": "Class C mix used for floor fills, lean concrete, non-critical structural elements", "type": "fact"}, {"text": "Mix proportions by weight: cement constant, aggregate weights vary with density", "type": "fact"}, {"text": "Mix water content: approximately 5-6 gallons per bag (40 kg) of cement", "type": "fact"}, {"text": "Strength development: 28-day cure is standard testing age for design strength", "type": "fact"}, {"text": "7-day strength typically 70% of 28-day strength", "type": "fact"}, {"text": "Type I (Ordinary Portland Cement): general purpose, most commonly used, moderate early strength", "type": "fact"}, {"text": "Type II (Modified Portland Cement): moderate sulfate resistance, used in areas with sulfate exposure", "type": "fact"}, {"text": "Type III (High Early Strength Portland Cement): high early strength, used where rapid strength gain needed", "type": "fact"}, {"text": "Type IV (Low Heat Portland Cement): low heat evolution, used in massive concrete elements to minimize thermal cracking", "type": "fact"}, {"text": "Type V (Sulfate Resistant Portland Cement): highest sulfate resistance, used in highly sulfate-exposed environments", "type": "fact"}, {"text": "Pozzolanic Cement (Type 1-P, 1-PM): contains volcanic ash, economical, reduced heat, improved durability", "type": "fact"}, {"text": "Blended Cements: combination of Portland cement with fly ash or slag", "type": "fact"}, {"text": "White Portland Cement: used for architectural/decorative applications", "type": "fact"}, {"text": "Fineness: measured in Blaine surface area (typically 3,000-4,000 cm²/g)", "type": "fact"}, {"text": "Strength Class: 32.5 N/mm², 42.5 N/mm², 52.5 N/mm² (International standards)", "type": "fact"}, {"text": "Slump: vertical displacement of concrete cone after removal of slump cone mold (mm or inches)", "type": "fact"}, {"text": "Typical slump ranges: 3-4\" for structural concrete (stiff), 4-6\" for general use (plastic), 6-8\" (fluid)", "type": "fact"}, {"text": "High slump (>8\") indicates excessive water, reduces strength and durability", "type": "fact"}, {"text": "Low slump (<2\") indicates stiff concrete, difficult to place, may have poor consolidation", "type": "fact"}, {"text": "Water-Cement Ratio (W/C): weight of water to weight of cement", "type": "fact"}, {"text": "Lower W/C ratio produces higher strength concrete (0.40-0.50 for structural work)", "type": "fact"}, {"text": "Higher W/C ratio produces more workable concrete but lower strength (0.60+ for floor fills)", "type": "fact"}, {"text": "W/C ratio controls hydration completeness and long-term durability", "type": "fact"}, {"text": "Standard W/C ratios: 0.40 (high strength), 0.45 (columns/beams), 0.50 (slabs), 0.60 (general work)", "type": "fact"}, {"text": "Workability increased by: higher slump, more sand, smaller aggregate, air entrainment", "type": "fact"}, {"text": "Fine aggregate (sand): particles less than 3/8\" (9.5 mm), typically 10-30% by weight", "type": "fact"}, {"text": "Coarse aggregate (gravel): particles larger than 3/8\", typically 60-75% by weight", "type": "fact"}, {"text": "Aggregate comprises 70-85% of concrete volume/weight", "type": "fact"}, {"text": "Coarse aggregate sizes: 3/8\", 1/2\", 3/4\", 1\" nominal maximum (ASTM designations)", "type": "fact"}, {"text": "Natural aggregates: from rivers/pits (granite, gravel); economical, consistent quality", "type": "fact"}, {"text": "Manufactured aggregates: crushed stone from quarries; angular, may have more fines", "type": "fact"}, {"text": "Recycled concrete aggregate (RCA): from demolished structures; emerging sustainable option", "type": "fact"}, {"text": "Aggregates must be clean, hard, angular, free from deleterious substances", "type": "fact"}, {"text": "Chloride content in aggregate restricted to <0.01% for reinforced concrete (corrosion risk)", "type": "fact"}, {"text": "Sulfate content (<1%) must be monitored to prevent expansive reactions", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-002-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Formwork (shuttering): temporary structure that holds concrete until it achieves strength", "type": "fact"}, {"text": "Forms must be: strong (withstand hydrostatic load), watertight, rigid, properly supported", "type": "fact"}, {"text": "Typical concrete pressure: hydrostatic load = 150 × height (ft) in lbs/sq ft (metric: 2.4 × h in kPa)", "type": "fact"}, {"text": "Form removal timing: 3-7 days for walls (ambient temperature dependent), 7-14 days for beams/slabs", "type": "fact"}, {"text": "Stripping sequence: props under beams removed last; columns first, then beams, then slabs", "type": "fact"}, {"text": "Common form materials: timber (plywood/timber), steel, plastic composites", "type": "fact"}, {"text": "Plywood grade for formwork: exterior veneer, minimum 3/4\" thickness for strength", "type": "fact"}, {"text": "Double waling (horizontal members) at 2-4 ft spacing typical for large forms", "type": "fact"}, {"text": "Diagonal bracing essential for form stability and prevention of blow-outs", "type": "fact"}, {"text": "Form release agents reduce adhesion and facilitate stripping", "type": "fact"}, {"text": "Placement (casting) must be done to prevent segregation of coarse aggregate", "type": "fact"}, {"text": "Drop height limited to 4-6 ft to prevent separation of cement paste from aggregate", "type": "fact"}, {"text": "Consolidation by vibration: external or internal vibrators compact concrete and remove air voids", "type": "fact"}, {"text": "Vibration duration: 10-30 seconds at each location (avoid over-vibration causing segregation)", "type": "fact"}, {"text": "Proper consolidation essential for strength, watertightness, and appearance", "type": "fact"}, {"text": "Curing: process of maintaining adequate moisture and temperature for hydration to continue", "type": "fact"}, {"text": "Early-age curing (first 7 days) most critical for strength development and durability", "type": "fact"}, {"text": "Curing methods: water spray/ponding, wet burlap coverings, plastic sheeting, membrane compounds, steam curing", "type": "fact"}, {"text": "Temperature requirements: minimum 50°F for 7 days (higher preferred), or 10°C minimum 28 days", "type": "fact"}, {"text": "Cold weather protection: insulation, heated enclosures when ambient temperature <50°F", "type": "fact"}, {"text": "Hot weather curing: cooling water, shade, wind breaks to prevent rapid evaporation and thermal cracking", "type": "fact"}, {"text": "Deformed bars (rebar): primary structural reinforcement, standard designations #3-#18 (10-57 mm diameter)", "type": "fact"}, {"text": "Bar diameters: #3=3/8\", #4=1/2\", #5=5/8\", #6=3/4\", #7=7/8\", #8=1\"", "type": "fact"}, {"text": "Yield strength: Grade 40 (40 ksi), Grade 60 (60 ksi, most common), Grade 75 (75 ksi)", "type": "fact"}, {"text": "Spacing requirements: minimum 1.5 × bar diameter, minimum 1.5\" clear (reinforced concrete standards)", "type": "fact"}, {"text": "Cover (concrete thickness from surface to rebar): 3/4\"-2\" depending on exposure conditions", "type": "fact"}, {"text": "Splicing: lap length typically 40-60 × bar diameter; welded splices alternative for large bars", "type": "fact"}, {"text": "Wire mesh (WWF): small diameter steel wires in grid, used for shrinkage/temperature control", "type": "fact"}, {"text": "Stirrups/Ties: lateral reinforcement in beams, spacing typically 6-12\" for shear/torsion control", "type": "fact"}, {"text": "Shear reinforcement: prevents diagonal cracking from shear forces", "type": "fact"}, {"text": "Temperature reinforcement: minimum 0.2% of concrete area for long-term crack control", "type": "fact"}, {"text": "Segregation: separation of coarse aggregate from cement paste (loss of strength and durability)", "type": "fact"}, {"text": "Bleeding: excess water rising to surface, causes weak surface layer (laitance)", "type": "fact"}, {"text": "Laitance: weak surface layer of cement and fines from bleeding (requires removal before overlay)", "type": "fact"}, {"text": "Honeycombing: voids from inadequate vibration, appears as aggregate pockets without paste", "type": "fact"}, {"text": "Thermal cracking: from temperature differential between mass interior and cooler surface", "type": "fact"}, {"text": "Shrinkage cracking: from drying shrinkage, common in slabs (W/C ratio and curing critical)", "type": "fact"}, {"text": "Spalling: surface deterioration from freeze-thaw cycles or chemical attack", "type": "fact"}, {"text": "Rebar corrosion: from chloride or carbonation reaching steel surface (cracking and spalling results)", "type": "fact"}, {"text": "Compressive strength testing: cylinder test (6\"×12\") at 7 and 28 days minimum", "type": "fact"}, {"text": "Core testing: extraction of cylinders from hardened concrete to verify in-place strength", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-002-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "ASTM A36: yield strength 36 ksi (250 MPa), tensile 58-80 ksi, general structural use", "type": "fact"}, {"text": "ASTM A572 Grade 50: yield 50 ksi (345 MPa), higher strength for lighter members", "type": "fact"}, {"text": "ASTM A588 (weathering steel): higher corrosion resistance, develops protective patina", "type": "fact"}, {"text": "Yield strength: stress at which material begins permanent deformation", "type": "fact"}, {"text": "Tensile strength: maximum stress before fracture (typically 1.5× yield strength)", "type": "fact"}, {"text": "Ductility: ability to deform under tension before failure (critical for seismic areas)", "type": "fact"}, {"text": "Common structural shapes: I-beams, channels, angles, tubes (HSS), W-sections", "type": "fact"}, {"text": "W-shape designations: W 18×35 (18\" nominal depth, 35 lbs per linear foot)", "type": "fact"}, {"text": "I-beams (older designation): less uniform flange thickness than W-beams", "type": "fact"}, {"text": "S-beams: American standard I-beams, tapered flanges (less efficient)", "type": "fact"}, {"text": "Bolted connections: A325 high-strength bolts (tension 120 ksi), A490 ultra-high-strength (150 ksi)", "type": "fact"}, {"text": "Snug-tight connections: adequate for static loads, simplest specification", "type": "fact"}, {"text": "Slip-critical connections: required for wind/seismic, bolts pre-tensioned to 70% of yield", "type": "fact"}, {"text": "Welded connections: AWS electrodes E60, E70 (tensile strength in ksi)", "type": "fact"}, {"text": "Fillet welds: most common, triangular cross-section", "type": "fact"}, {"text": "Butt welds: complete joint penetration for tension members", "type": "fact"}, {"text": "Weld size: minimum 3/8\" fillet for main connections, controlled by material thickness", "type": "fact"}, {"text": "Field splices: typically bolted; shop splices may be welded for economy", "type": "fact"}, {"text": "Connection gusset plates: distribute forces from multiple members at joints", "type": "fact"}, {"text": "High-strength bolts prevent connection slip under service loads", "type": "fact"}, {"text": "Shop fabrication: most members cut, drilled, welded in controlled environment", "type": "fact"}, {"text": "Field assembly: bolted connections primary assembly method", "type": "fact"}, {"text": "Camber: slight upward curve in beams to offset dead load deflection", "type": "fact"}, {"text": "Mill scale: oxidized surface removed by wire brushing or sandblasting before painting", "type": "fact"}, {"text": "Base coat primer: rich mill prime (zinc-rich) prevents corrosion during storage/assembly", "type": "fact"}, {"text": "Fireproofing methods: spray-applied insulation, boards, columns encasement", "type": "fact"}, {"text": "Spray fireproofing: mineral fiber, gypsum, intumescent coatings", "type": "fact"}, {"text": "Fire rating: time to reach critical temperature (typically 1000°F for 50 ksi steel)", "type": "fact"}, {"text": "Intumescent paints: swell when heated, insulate steel from fire", "type": "fact"}, {"text": "Structural steel expands 0.0000065 in./in./°F (expansion joints required in long buildings)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-003-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Gauge system: higher gauge number = thinner material (inverse relationship)", "type": "fact"}, {"text": "GI Gauge 24 (0.020-0.024\" thick): light roofing, siding, gutters, drains", "type": "fact"}, {"text": "GI Gauge 22 (0.027-0.032\" thick): heavier roofing, structural siding, flashing", "type": "fact"}, {"text": "GI Gauge 20 (0.035-0.043\" thick): structural members, heavy-duty applications", "type": "fact"}, {"text": "GI Gauge 18 (0.047-0.054\" thick): major structural, heavy flashing, expansion joints", "type": "fact"}, {"text": "Galvanizing process: hot-dip coating of zinc (100-150 microns typical)", "type": "fact"}, {"text": "Zinc coating mass: 25 microns/side (G60), 45 microns/side (G90) common specifications", "type": "fact"}, {"text": "Advantage: self-healing corrosion resistance through zinc cathodic protection", "type": "fact"}, {"text": "Performance: 15-30+ year lifespan depending on environment and coating thickness", "type": "fact"}, {"text": "Coastal environments require higher coating mass (G90 preferred over G60)", "type": "fact"}, {"text": "Flashing: metal barriers preventing water penetration at building joints", "type": "fact"}, {"text": "Roof-to-wall flashing: extends 4-6\" up wall, turned down under shingles", "type": "fact"}, {"text": "Eaves flashing: horizontal metal at gutter line, directs water into gutter", "type": "fact"}, {"text": "Valley flashing: where two roof slopes meet, 4-6\" width minimum each side", "type": "fact"}, {"text": "Chimney flashing: base flashing below cricket, step flashing up sides", "type": "fact"}, {"text": "Window/door head flashing: above opening, extends over frame edges", "type": "fact"}, {"text": "Sill pans: sloped pans below windows, must slope outward 2-3% minimum", "type": "fact"}, {"text": "Gutter size: 5\" gutters for roof areas <600 sq ft, 6\" for larger areas", "type": "fact"}, {"text": "Gutter slope: minimum 0.5\" per 10 ft length toward downspouts", "type": "fact"}, {"text": "Downspout sizing: 1\" diameter per 100 sq ft of roof area (minimum 2\" diameter)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-003-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Annealed glass: slow cooling, no internal stress, breaks into large jagged shards", "type": "fact"}, {"text": "Hazard: not recommended for doors, low heights, high-impact areas (code restrictions)", "type": "fact"}, {"text": "Tempered glass (safety glass): rapid cooling creates compression surface stress", "type": "fact"}, {"text": "Tempered strength: 4-5× stronger than annealed in bending", "type": "fact"}, {"text": "Tempered breakage: shatters into small cubes (safe, but complete loss of transparency)", "type": "fact"}, {"text": "Laminated glass: two or more sheets bonded with PVB (polyvinyl butyral) interlayer", "type": "fact"}, {"text": "Laminated safety: holds together when broken (like windshield), reduces injury risk", "type": "fact"}, {"text": "Impact resistance: laminated better than tempered for forced entry prevention", "type": "fact"}, {"text": "Float glass: most common clear glass produced by floating on molten tin bath", "type": "fact"}, {"text": "Tinted glass: reduces solar transmission and glare (bronze, gray, green colors)", "type": "fact"}, {"text": "Reflective glass: metallic coating reduces heat gain and light transmission", "type": "fact"}, {"text": "IGU (Double-Glazed/Double-Pane): two glass panes separated by air/gas gap (typically 6-13 mm)", "type": "fact"}, {"text": "Air gap: reduces heat transfer vs. single pane, typically 1/2\" gap optimal", "type": "fact"}, {"text": "U-value (heat transmission coefficient): lower = better insulation", "type": "fact"}, {"text": "Single-pane window: U-value ~1.0 Btu/(hr·°F·sq ft)", "type": "fact"}, {"text": "Double-pane air-filled: U-value ~0.49 Btu/(hr·°F·sq ft)", "type": "fact"}, {"text": "Triple-pane or gas-filled (argon): U-value ~0.25-0.35 Btu/(hr·°F·sq ft)", "type": "fact"}, {"text": "SHGC (Solar Heat Gain Coefficient): fraction of solar energy transmitted (0-1 scale)", "type": "fact"}, {"text": "Low SHGC (0.25-0.35): reduces cooling loads in hot climates", "type": "fact"}, {"text": "High SHGC (0.50-0.80): maximizes passive solar heating in cold climates", "type": "fact"}, {"text": "Low-E (low-emissivity) coating: metallic film reduces infrared transmission", "type": "fact"}, {"text": "Spacer types: aluminum (conductive), insulated spacers (foam, silicone)", "type": "fact"}, {"text": "Wet glazing: putty or sealant as primary weather seal (older windows)", "type": "fact"}, {"text": "Structural glazing: silicone sealant as primary structural member and weather seal", "type": "fact"}, {"text": "Setting blocks: elastomer pads supporting glass in frame (prevent point loading)", "type": "fact"}, {"text": "Bite depth: overlap of glass into frame (typically 3/8\"-1\" minimum)", "type": "fact"}, {"text": "Bead depth: depth of sealant/putty behind glass (typically 1/4\"-1/2\")", "type": "fact"}, {"text": "Sealant movement capability: ±25% for polyurethane, ±50% for silicone typical", "type": "fact"}, {"text": "Joint design: two-sided sealant required (reduced stress vs. three-sided)", "type": "fact"}, {"text": "Shimming: maintain level and square during installation", "type": "fact"}, {"text": "Drainage and weeps: base frame must have drain paths for water management", "type": "fact"}, {"text": "Gasket glazing: neoprene or silicone gaskets mechanical retention (no sealant)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-003-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Shallow foundations: footings, foundations in bearing soils <3-4 ft below grade", "type": "fact"}, {"text": "Deep foundations: piles, caissons for weak soils or deep bearing strata", "type": "fact"}, {"text": "Spread footings: rectangular/square pads distributing column loads to soil", "type": "fact"}, {"text": "Soil bearing capacity: varies 1000-6000 psf for typical soils (geotechnical investigation required)", "type": "fact"}, {"text": "Foundation depth: minimum 3-4 ft below final grade (below frost line for freeze-thaw regions)", "type": "fact"}, {"text": "Frost line: depth below grade where soil stays above freezing year-round (varies by latitude)", "type": "fact"}, {"text": "Sub-base preparation: remove organic material, compact to 95% Proctor density", "type": "fact"}, {"text": "Gravel sub-base: 4-6\" layer of compacted gravel improves drainage and bearing", "type": "fact"}, {"text": "Ground improvement: soil stabilization, grouting, pile underpinning for weak soils", "type": "fact"}, {"text": "Geotechnical investigation: boring, lab testing, bearing capacity determination essential", "type": "fact"}, {"text": "Timber piles: wood poles, butt diameter 12-14\", point diameter 6-8\"", "type": "fact"}, {"text": "Capacity per timber pile: 10-40 tons depending on length and soil", "type": "fact"}, {"text": "H-piles (H-sections): structural steel H-sections, capacity 50-100+ tons", "type": "fact"}, {"text": "Pipe piles: steel pipe filled with concrete, capacity 50-150+ tons", "type": "fact"}, {"text": "Cast-in-place concrete piles: drilled holes filled with reinforced concrete", "type": "fact"}, {"text": "Precast concrete piles: manufactured off-site, driven into soil", "type": "fact"}, {"text": "Batter piles: angled piles resisting lateral loads (45° typical angle)", "type": "fact"}, {"text": "Pile group: multiple piles with cap distributing loads, spacing ≥3× pile diameter", "type": "fact"}, {"text": "Negative skin friction: soil settlement relative to pile causes downward drag", "type": "fact"}, {"text": "Pile testing: static load test or dynamic driving analysis (PDA) verifies capacity", "type": "fact"}, {"text": "Excavation: removal of soil to design elevation", "type": "fact"}, {"text": "Compaction: mechanical densification to reduce settlement", "type": "fact"}, {"text": "Standard Proctor test: 12,400 lbf·ft/cu ft maximum dry density (100% reference)", "type": "fact"}, {"text": "Compaction specification: 90-95% Standard Proctor, 95-100% Modified Proctor", "type": "fact"}, {"text": "Granular sub-base (Class 1): size 3/4\"-3/8\", <5% passing #200 sieve, free-draining", "type": "fact"}, {"text": "Select fill material: <12\" minus size, <8% passing #200, high bearing capacity", "type": "fact"}, {"text": "Slope stability: steeper cuts require buttressing or flatter slopes", "type": "fact"}, {"text": "Drainage: foundation drainage paths prevent hydrostatic pressure accumulation", "type": "fact"}, {"text": "Swale/ditch grading: 2% minimum slope for surface water runoff", "type": "fact"}, {"text": "Compaction equipment: sheepsfoot rollers, vibratory rollers, plate compactors", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-004-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Light-frame construction: 2×4, 2×6 studs at 16\" or 24\" o.c. (on-center)", "type": "fact"}, {"text": "Rim board (header/band joist): edge beam enclosing floor perimeter", "type": "fact"}, {"text": "Beam spacing: typical residential 12-16 ft span on 16\" or 24\" centers", "type": "fact"}, {"text": "Floor joists: 2×6 (typical), 2×8, 2×10, 2×12 depending on span and load", "type": "fact"}, {"text": "Joist spans: 2×6 can span 9-10 ft, 2×10 can span 15-16 ft (varies by grade/spacing)", "type": "fact"}, {"text": "Bridging: cross-bracing between joists prevents lateral movement (1×4 or metal)", "type": "fact"}, {"text": "Blocking: solid pieces between joists at midspan reduce deflection and vibration", "type": "fact"}, {"text": "Subflooring: 3/4\" plywood or OSB nailed/screwed to joists (structural diaphragm)", "type": "fact"}, {"text": "Rim sealing: caulk/foam seals rim board reducing air infiltration and heat loss", "type": "fact"}, {"text": "Cantilever: joists extended beyond support (typically 12-24\" maximum)", "type": "fact"}, {"text": "Slab-on-grade: concrete slab on soil/sub-base (single-story typical)", "type": "fact"}, {"text": "Thickness: 4-6\" structural slab, 2-3\" fill slab (unreinforced)", "type": "fact"}, {"text": "Reinforcement: wire mesh or rebar for crack control", "type": "fact"}, {"text": "Isolation joint: separates slab from walls, expansion around perimeter", "type": "fact"}, {"text": "Control joints: grooves or sawn cuts at 4-6 ft intervals control shrinkage cracking", "type": "fact"}, {"text": "One-way slab: supported along two edges, reinforcement primarily one direction", "type": "fact"}, {"text": "Two-way slab: supported on all four sides (more efficient for square bays)", "type": "fact"}, {"text": "Beam-and-slab system: beams support slab, columns support beams (multi-story)", "type": "fact"}, {"text": "Flat plate: slab directly supported on columns (no beams), columns form drop panels", "type": "fact"}, {"text": "Waffle slab: grid of ribs with domes/pans creates lighter slab", "type": "fact"}, {"text": "Hollow core slab: precast concrete planks with voids (floor and roof use)", "type": "fact"}, {"text": "Steel beams: W, S, C shapes spanning typically 30-60 ft for office buildings", "type": "fact"}, {"text": "Decking: metal deck (24 or 20 gauge galvanized) spans between beams", "type": "fact"}, {"text": "Non-composite: deck supported on beams, no load transfer participation", "type": "fact"}, {"text": "Composite system: shear studs welded to beam top bond deck to beam", "type": "fact"}, {"text": "Composite action: deck and beam act together, higher strength, less deflection", "type": "fact"}, {"text": "Shear studs: headed studs 3/4\"-1\" diameter, spacing 12-36\" typical", "type": "fact"}, {"text": "Floor depth: typical 24-30\" total (deck + beam depth) for 30-40 ft spans", "type": "fact"}, {"text": "Edge angles: angle iron around perimeter for fireproofing attachment/edge support", "type": "fact"}, {"text": "Vibration: composite floors have better damping than bare steel (human comfort)", "type": "fact"}, {"text": "Pan decking: 2-3\" concrete topping over metal deck (80-120 psf added load)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-004-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Roof pitch: slope expressed as rise:run (12:12 = 45°, 4:12 = ~19°)", "type": "fact"}, {"text": "Minimum pitch for water shedding: 2:12 for asphalt shingles, 4:12 for slate", "type": "fact"}, {"text": "Rafters: sloped members spanning from plate to ridge, 2×6-2×12 depending on span", "type": "fact"}, {"text": "Rafter spacing: 16\" or 24\" o.c. typical for residential (load dependent)", "type": "fact"}, {"text": "Collar ties: horizontal bracing reducing rafter thrust (typically at upper 1/3 of span)", "type": "fact"}, {"text": "Ceiling joists: horizontal tie between rafters at top plate level (resists outward thrust)", "type": "fact"}, {"text": "Ridge board: horizontal member at apex receiving rafters on each side", "type": "fact"}, {"text": "Lookouts: rafter extensions for overhang (16-24\" typical for residential)", "type": "fact"}, {"text": "Eaves: soffit (underside of overhang) and fascia (vertical edge board) for finish", "type": "fact"}, {"text": "Roof decking: 1/2\"-3/4\" plywood or OSB nailed 6\" o.c. edges, 12\" o.c. field", "type": "fact"}, {"text": "Asphalt shingles: fiberglass mat + asphalt + mineral granules", "type": "fact"}, {"text": "Sizes: 3-tab shingles (standard), dimensional/architectural (premium appearance)", "type": "fact"}, {"text": "Weight: 235-320 lbs per square (100 sq ft) determines durability", "type": "fact"}, {"text": "Lifespan: 20-year (budget), 30-year (standard), 50-year (premium warranties)", "type": "fact"}, {"text": "Installation: 4-6 nails per shingle, offset pattern for overlap", "type": "fact"}, {"text": "Underlayment: 15# felt or synthetic mat reduces wind damage and adds weather protection", "type": "fact"}, {"text": "Built-up roof: alternating layers of felt and bitumen creating 3-5 ply membrane", "type": "fact"}, {"text": "Single-ply membrane (EPDM, TPO, PVC): rubber or plastic sheets adhered/mechanized", "type": "fact"}, {"text": "EPDM: black rubber, 45-60 mil thickness, most economical, susceptible to puncture", "type": "fact"}, {"text": "TPO: thermoplastic, white reflective, 45-60 mil, better puncture resistance", "type": "fact"}, {"text": "PVC: highest quality, white, 45-60 mil, excellent durability (most expensive)", "type": "fact"}, {"text": "R-value: thermal resistance (°F·sq ft·hr/Btu) - higher = better insulation", "type": "fact"}, {"text": "Fiberglass batts: R-3.2 per inch (most common residential insulation)", "type": "fact"}, {"text": "Mineral wool batts: R-3.3-3.6 per inch (better fire resistance, sound absorption)", "type": "fact"}, {"text": "Cellulose loose-fill: R-3.2-3.6 per inch (recycled paper, good air sealing)", "type": "fact"}, {"text": "Rigid foam (XPS): R-5 per inch (extruded polystyrene, moisture resistant)", "type": "fact"}, {"text": "Rigid foam (EPS): R-3.8-4.2 per inch (expanded polystyrene, economical)", "type": "fact"}, {"text": "Spray foam (closed-cell): R-6 per inch (excellent air sealing, highest cost)", "type": "fact"}, {"text": "Spray foam (open-cell): R-3.5 per inch (lower cost, permeable)", "type": "fact"}, {"text": "Roof insulation minimum: R-19 (6\") most climates, R-30-38 for cold climates", "type": "fact"}, {"text": "Vapor barrier/retarder: 6-mil polyethylene (old practice) or kraft-faced insulation", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-004-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Wythe: single-unit-width masonry layer (4\" for brick, 8\" for blocks)", "type": "fact"}, {"text": "Bond pattern: decorative and structural interlocking arrangement", "type": "fact"}, {"text": "Running bond: offset courses, most common pattern for strength", "type": "fact"}, {"text": "Header bond: every 6th course runs across full thickness, ties wythes together", "type": "fact"}, {"text": "Common bond: pattern of 5 stretcher courses + 1 header course", "type": "fact"}, {"text": "Stack bond: vertical alignment (less structural, more contemporary appearance)", "type": "fact"}, {"text": "Cavity wall: outer wythe (brick/stone) + cavity (2-4\") + inner wythe (blocks)", "type": "fact"}, {"text": "Cavity function: allows for insulation, reduces moisture penetration", "type": "fact"}, {"text": "Weep holes: vertical openings in base wythe every 16-24\" o.c. drain cavity moisture", "type": "fact"}, {"text": "Flashing: horizontal metal strips in cavity direct water to weeps", "type": "fact"}, {"text": "Interior partitions: 2×4 studs at 16\" o.c. standard (24\" for non-load-bearing)", "type": "fact"}, {"text": "Top and bottom plates: 2×4 members anchored to structure above/below", "type": "fact"}, {"text": "Sole plate to concrete: anchored with 1/2\" bolts 4-6 ft o.c. (5 psf of wall minimum)", "type": "fact"}, {"text": "Studs: spaced 16\" o.c. (on-center) allows standard 4 ft wide panels/materials", "type": "fact"}, {"text": "Corner bracing: additional studs at intersections (three-stud corners)", "type": "fact"}, {"text": "Openings: headers size determined by span (2×4-2×12 depending on span)", "type": "fact"}, {"text": "Fire rating: 1-hour rated walls require 5/8\" Type X drywall on both sides", "type": "fact"}, {"text": "Sound isolation: resilient channels reduce sound transmission (R-60+ for STC)", "type": "fact"}, {"text": "Fire blocking: 2×4 blocking at 4 ft height continuous around perimeter", "type": "fact"}, {"text": "Rough-in: electrical, plumbing, HVAC openings sized before drywall installation", "type": "fact"}, {"text": "Curtain wall: non-load-bearing exterior envelope, supports own weight + wind loads", "type": "fact"}, {"text": "Stick system: mullions and transoms assembled on-site (labor-intensive)", "type": "fact"}, {"text": "Unit system: pre-assembled units installed floor-by-floor (faster, more expensive)", "type": "fact"}, {"text": "Structural sealant: silicone bonds glass/panels to frame (no mechanical fasteners visible)", "type": "fact"}, {"text": "Glazing gaskets: neoprene or silicone compression seals around glass", "type": "fact"}, {"text": "Anchor/connections: bolted to building structure typically every floor level", "type": "fact"}, {"text": "Thermal breaks: insulating spacers reduce heat transfer through metal frame", "type": "fact"}, {"text": "Drainage: internal gutter and drain paths manage water inside frame", "type": "fact"}, {"text": "Pressure equalization: exterior chamber reduces pressure differential on sealants", "type": "fact"}, {"text": "Access: typical systems allow individual panel replacement without disturbing neighbors", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-004-04';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "MasterFormat: industry-standard numbering system for construction specifications", "type": "fact"}, {"text": "Divisions 01-14: 2020 edition (combined from previous 16-division structure)", "type": "fact"}, {"text": "Division 01: General Requirements, Conditions, Supplementary Requirements", "type": "fact"}, {"text": "Divisions 02-04: Existing Conditions, Concrete, Masonry", "type": "fact"}, {"text": "Divisions 05-07: Metals, Wood, Plastics, Thermal/Moisture Protection", "type": "fact"}, {"text": "Divisions 08-10: Openings, Finishes, Specialties", "type": "fact"}, {"text": "Divisions 11-14: Equipment, Furnishings, Fire Suppression, Electrical, Mechanical", "type": "fact"}, {"text": "Section structure: Part 1 (General), Part 2 (Products), Part 3 (Execution)", "type": "fact"}, {"text": "Performance specifications: describe function/results, not specific materials", "type": "fact"}, {"text": "Descriptive specifications: specify exact materials, brands, or equal", "type": "fact"}, {"text": "Proprietary specifications: single manufacturer allowed (justified only)", "type": "fact"}, {"text": "Standard specifications: reference industry standards (ASTM, ACI, AWS, etc.)", "type": "fact"}, {"text": "Part 1 General: scope, submittals, quality assurance, warranty requirements", "type": "fact"}, {"text": "Submittals: product data, shop drawings, test reports, samples for review", "type": "fact"}, {"text": "Quality Assurance: testing, inspection, certification requirements", "type": "fact"}, {"text": "Part 2 Products: material grades, standards, performance criteria, options", "type": "fact"}, {"text": "Concrete spec includes: mix design, slump, air content, compressive strength", "type": "fact"}, {"text": "Steel spec includes: grade, yield strength, mill certs, weld requirements", "type": "fact"}, {"text": "Masonry spec includes: unit type, compressive strength, mortar type, grout strength", "type": "fact"}, {"text": "Part 3 Execution: installation methods, workmanship standards, testing", "type": "fact"}, {"text": "Workmanship standard: \"executed in workmanlike manner, consistent with good trade practice\"", "type": "fact"}, {"text": "Tolerances: dimensional, straightness, plumbness critical to specify", "type": "fact"}, {"text": "Inspection: hold points, witness testing, final acceptance criteria", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-004-05';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Recycled content: percentage of material derived from post-consumer/post-industrial waste", "type": "fact"}, {"text": "Recycled concrete aggregate (RCA): from demolished structures, reduces virgin aggregate use", "type": "fact"}, {"text": "Recycled steel: primary content from melted structural/rebar steel, 100% recyclable", "type": "fact"}, {"text": "Recycled asphalt: reclaimed pavement reused in new asphalt mixes (up to 30%)", "type": "fact"}, {"text": "Recycled plastic lumber: plastic lumber from recycled bottles/bags, maintenance-free", "type": "fact"}, {"text": "Bamboo: renewable alternative to wood, strength comparable to hardwoods, faster growth", "type": "fact"}, {"text": "Cork: renewable material from cork oak bark, used for flooring and insulation", "type": "fact"}, {"text": "Salvaged wood: reclaimed timbers from demolished buildings, reduced environmental impact", "type": "fact"}, {"text": "Salvaged masonry: reused bricks/blocks reduce demolition waste", "type": "fact"}, {"text": "Pozzolanic materials: fly ash, slag reduce portland cement content (lower embodied energy)", "type": "fact"}, {"text": "Embodied energy: total energy required to manufacture and transport material", "type": "fact"}, {"text": "Carbon footprint: greenhouse gas emissions associated with material lifecycle", "type": "fact"}, {"text": "Portland cement production: 5-8% of global CO2 emissions (significant contributor)", "type": "fact"}, {"text": "Supplementary cementitious materials: fly ash, slag reduce cement content by 20-40%", "type": "fact"}, {"text": "Recycled content materials: lower embodied energy than virgin materials", "type": "fact"}, {"text": "Local materials: reduced transportation energy compared to imported materials", "type": "fact"}, {"text": "Manufacturing efficiency: modern facilities more efficient than older plants", "type": "fact"}, {"text": "Operational energy: material''s effect on building energy use over lifetime (more significant than embodied)", "type": "fact"}, {"text": "End-of-life: recyclability and reuse reduce lifetime environmental impact", "type": "fact"}, {"text": "Life Cycle Assessment (LCA): comprehensive analysis of material environmental impact", "type": "fact"}, {"text": "LEED (Leadership in Energy and Environmental Design): point-based certification system", "type": "fact"}, {"text": "LEED Material points: recycled content, regional materials, rapidly renewable", "type": "fact"}, {"text": "BREEAM (Building Research Establishment Environmental Assessment Method): UK/EU standard", "type": "fact"}, {"text": "Living Building Challenge: most stringent environmental performance standard", "type": "fact"}, {"text": "Green Globes: alternative North American green building rating system", "type": "fact"}, {"text": "EPD (Environmental Product Declaration): standardized environmental impact reporting", "type": "fact"}, {"text": "VOC emissions: volatile organic compound limits in paints, sealants, adhesives", "type": "fact"}, {"text": "Formaldehyde-free: materials without formaldehyde binders (plywood, insulation)", "type": "fact"}, {"text": "Rapidly renewable materials: materials harvested in <10 years (bamboo, cork, linoleum)", "type": "fact"}, {"text": "Water conservation materials: low-flow fixtures, permeable paving reduce consumption", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-005-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Building envelope: walls, roof, foundation control heat transfer", "type": "fact"}, {"text": "Exterior walls: minimum R-13 (residential), R-19 (cold climates)", "type": "fact"}, {"text": "Roof insulation: minimum R-19, R-30-38 in northern climates", "type": "fact"}, {"text": "Foundation walls: R-7.5 (interior), R-15 (exterior) below grade", "type": "fact"}, {"text": "Thermal bridge: framing reduces insulation effectiveness 15-25% typical", "type": "fact"}, {"text": "Continuous insulation: exterior insulation layer reduces thermal bridging", "type": "fact"}, {"text": "Air sealing: preventing air infiltration more cost-effective than additional insulation", "type": "fact"}, {"text": "Infiltration rate: <7 air changes per hour at 50 Pa (blower door test) standard", "type": "fact"}, {"text": "Passive House standard: <0.6 air changes per hour, ≤15 kWh/m²/yr heating energy", "type": "fact"}, {"text": "Solar orientation: positioning for winter gain, summer shading critical in passive design", "type": "fact"}, {"text": "U-value window: 0.30-0.35 efficient, <0.25 high-performance (triple-glazed)", "type": "fact"}, {"text": "Solar Heat Gain Coefficient (SHGC): 0.23-0.31 (cold climate), 0.15-0.23 (hot climate)", "type": "fact"}, {"text": "Visible Transmittance (VT): percentage of visible light transmitted (0.40-0.60 typical)", "type": "fact"}, {"text": "Air leakage: <0.3 cfm/sq ft (cubic feet per minute per square foot) at 75 Pa", "type": "fact"}, {"text": "Frame material: vinyl/fiberglass more efficient than aluminum (no thermal break)", "type": "fact"}, {"text": "Thermal breaks: insulating material between frame exterior/interior reduces conduction", "type": "fact"}, {"text": "Low-E coatings: reduce infrared transmission 40-50% while maintaining light transmittance", "type": "fact"}, {"text": "Argon fill: gas between panes reduces convection (U-value reduction ~3%)", "type": "fact"}, {"text": "Krypton fill: more expensive, R-value ~2% better than argon", "type": "fact"}, {"text": "Installation: proper sealing reduces air leakage (larger effect than product rating)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-005-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Low-flow fixtures: 1.5 gpm (faucets), 1.28 gpm (toilets) vs. standard 2.5-3.5 gpm", "type": "fact"}, {"text": "Water reduction potential: 30-50% with efficient fixtures", "type": "fact"}, {"text": "Rainwater harvesting: cisterns collect roof water for irrigation/non-potable use", "type": "fact"}, {"text": "Permeable paving: allows water infiltration reducing runoff (rain gardens, bioswales)", "type": "fact"}, {"text": "Green roofs: vegetation layer absorbs water, reduces runoff 40-80% depending on depth", "type": "fact"}, {"text": "Greywater systems: reuse non-potable water (showers, sinks) for landscape irrigation", "type": "fact"}, {"text": "Stormwater management: detention basins, swales, detention ponds reduce downstream flooding", "type": "fact"}, {"text": "Impervious surface: asphalt, concrete increase runoff; limit to 75% of site area", "type": "fact"}, {"text": "Site grading: direct runoff to infiltration areas, reduce hardscape percentage", "type": "fact"}, {"text": "Native plantings: require less water than turf once established (xeriscaping principles)", "type": "fact"}, {"text": "VOCs (Volatile Organic Compounds): off-gas from materials, cause indoor air pollution", "type": "fact"}, {"text": "Common VOC sources: paints, sealants, adhesives, flooring, furniture, finishes", "type": "fact"}, {"text": "Formaldehyde: carcinogenic VOC found in composite wood products, insulation", "type": "fact"}, {"text": "Low-VOC paints: <50-100 g/L VOC content (vs. standard 300-400 g/L)", "type": "fact"}, {"text": "Natural finishes: plant-based oils, waxes alternative to synthetic polyurethane", "type": "fact"}, {"text": "Sealants/adhesives: low-VOC urethanes and silicones reduce off-gassing", "type": "fact"}, {"text": "Ventilation: mechanical fresh air exchange removes VOCs (6-8 air changes/hour minimum)", "type": "fact"}, {"text": "Off-gassing time: 30-90 days typical for new materials before VOC levels decline", "type": "fact"}, {"text": "Material selection: specify low-VOC products for healthier indoor environment", "type": "fact"}, {"text": "Testing: chemical analysis verifies low-VOC claims; GreenGuard/FloorScore certifications", "type": "fact"}, {"text": "Vapor drive: water vapor movement from warm side to cold side (winter heating climates)", "type": "fact"}, {"text": "Vapor barrier (6-mil polyethylene): nearly impermeable, on interior (warm side)", "type": "fact"}, {"text": "Vapor retarder: kraft-faced insulation (~1 perm), permits some vapor movement", "type": "fact"}, {"text": "Permeable insulation: open-cell foam allows vapor movement (less mold risk)", "type": "fact"}, {"text": "Drying potential: ability of wall assembly to dry toward interior/exterior", "type": "fact"}, {"text": "Condensation: occurs when vapor reaches dew point temperature on cold surface", "type": "fact"}, {"text": "Mold prevention: maintain <60% relative humidity, proper ventilation essential", "type": "fact"}, {"text": "Humidity control: mechanical exhaust in bathrooms/kitchens, dehumidifiers in humid climates", "type": "fact"}, {"text": "Rain screen: ventilated cavity allows walls to dry (exterior sheathing drying path)", "type": "fact"}, {"text": "Material vapor permeability: measured in perms; allows specification of vapor movement properties", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-005-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Construction waste: 10-30% of materials wasted on typical projects (source: EPA)", "type": "fact"}, {"text": "Waste reduction: efficient design, careful planning, accurate estimating reduce waste", "type": "fact"}, {"text": "Prefabrication: off-site manufacturing reduces on-site waste generation", "type": "fact"}, {"text": "Design for deconstruction: modular systems facilitate future material recovery", "type": "fact"}, {"text": "Source separation: segregate waste for recycling by material type (wood, metal, concrete)", "type": "fact"}, {"text": "Wood waste: diverted for mulch, animal bedding, or energy recovery (60% of construction waste)", "type": "fact"}, {"text": "Concrete waste: crushed for recycled aggregate or fill material", "type": "fact"}, {"text": "Metal waste: high recovery rate (95%+) economical recycling market", "type": "fact"}, {"text": "Hazardous waste: proper handling/disposal for asbestos, lead, PCBs critical", "type": "fact"}, {"text": "Waste reduction goals: 75% diversion from landfills achievable with good management", "type": "fact"}, {"text": "Circular economy: minimize waste through design for reuse, repair, recycling", "type": "fact"}, {"text": "Take-back programs: manufacturers accept products for recycling (flooring, carpet)", "type": "fact"}, {"text": "Material banks: demolition salvage facilities accumulate materials for reuse", "type": "fact"}, {"text": "Deconstruction: systematic removal of materials for reuse vs. demolition", "type": "fact"}, {"text": "Salvage value: architectural elements (doors, hardware, fixtures) have resale value", "type": "fact"}, {"text": "Leasing model: manufacturer retains ownership, recovery of materials at end-of-life", "type": "fact"}, {"text": "Modular systems: components replaceable extending product life", "type": "fact"}, {"text": "Biodegradable materials: natural fibers, cork compost at end-of-life", "type": "fact"}, {"text": "Upcycling: adding value to waste materials (glass aggregate in concrete)", "type": "fact"}, {"text": "Extended producer responsibility: manufacturer liability for product end-of-life encourages design for recovery", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-005-04';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Asbestos: carcinogenic mineral fiber in insulation, acoustic tiles, vinyl-asbestos floor tile", "type": "fact"}, {"text": "Lead paint: common pre-1978, toxic to children, neurotoxicity risk", "type": "fact"}, {"text": "PCBs (Polychlorinated Biphenyls): in old electrical transformers, sealants (EPA banned 1979)", "type": "fact"}, {"text": "Mercury: in old fluorescent fixtures; requires special handling/disposal", "type": "fact"}, {"text": "Radon: naturally occurring radioactive gas from soil (radon-resistant construction required)", "type": "fact"}, {"text": "Mold: moisture problems promote toxic mold growth (respiratory, allergenic)", "type": "fact"}, {"text": "Phthalates: plasticizers in vinyl, exposure linked to developmental effects", "type": "fact"}, {"text": "Formaldehyde: carcinogenic, found in composite wood and some foams", "type": "fact"}, {"text": "Biological contaminants: dust mites, pet dander, mold spores from humidity", "type": "fact"}, {"text": "Proper ventilation: continuous fresh air exchange removes contaminants", "type": "fact"}, {"text": "OSHA requirements: safety standards, fall protection, scaffolding safety mandatory", "type": "fact"}, {"text": "PPE (Personal Protective Equipment): respirators, hard hats, safety glasses, gloves", "type": "fact"}, {"text": "Asbestos removal: licensed contractors, negative pressure enclosures required", "type": "fact"}, {"text": "Dust control: wet cutting, HEPA filtration reduces silica exposure", "type": "fact"}, {"text": "Silicosis: occupational lung disease from crystalline silica inhalation", "type": "fact"}, {"text": "Concrete finishing: skin irritation from alkaline concrete exposure", "type": "fact"}, {"text": "Chemical exposure: safety data sheets (SDS) for all hazardous materials", "type": "fact"}, {"text": "Noise control: hearing protection above 85 dB, engineering controls preferred", "type": "fact"}, {"text": "Heat stress: hydration, rest breaks during hot weather work", "type": "fact"}, {"text": "Ergonomics: proper lifting techniques, mechanical assists reduce musculoskeletal injury", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-005-05';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "National Building Code (NBC): Philippine building standards mandatory compliance", "type": "fact"}, {"text": "Energy Conservation Design (ECD) code: Part 6 of NBC addresses energy efficiency", "type": "fact"}, {"text": "Minimum insulation: R-11 walls, R-19 attics (metric equivalents in Philippines)", "type": "fact"}, {"text": "Window performance: U-value limits vary by climate zone", "type": "fact"}, {"text": "Orientation: south-facing orientation in tropical climates requires shading", "type": "fact"}, {"text": "Natural ventilation: ceiling fans, cross-ventilation reduce mechanical cooling load", "type": "fact"}, {"text": "Thermal mass: concrete/masonry provides diurnal temperature moderation in tropics", "type": "fact"}, {"text": "Vernacular architecture: indigenous design principles reflect climate (elevated structures, deep eaves)", "type": "fact"}, {"text": "Typhoon considerations: wind resistance, structural redundancy critical for Philippines", "type": "fact"}, {"text": "Flood resilience: elevation, amphibious structures, water-resistant materials in flood zones", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-MATL-005-06';

